import base64, json, os, runpy, shutil, subprocess, sys, time
from pathlib import Path
os.environ.update(HF_HUB_DISABLE_XET="1", HF_HUB_DISABLE_PROGRESS_BARS="1", HF_HOME="/tmp/e52-hf",
                  OMP_NUM_THREADS="2", VLLM_WORKER_MULTIPROC_METHOD="spawn")
started = time.time()
out = Path("/kaggle/working/e62-qwen-d")
out.mkdir(parents=True, exist_ok=True)
subprocess.run(["nvidia-smi"], check=True)
root = Path("/tmp/aimo-e52")
for name, encoded in json.loads('{"datagen/perturb/sample.py": "", "datagen/perturb/answers.py": "", "datagen/tokenizer_check.py": "", "datagen/extract_features.py": "", "scripts/kaggle_cuda_setup.py": "", "scripts/kaggle_process_guard.py": "", "data/e62/pool.parquet": "", "protocols/E62_PROTOCOL.md": ""}').items():
    dest = root / name
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(base64.b64decode(encoded))
cuda = runpy.run_path(str(root / "scripts/kaggle_cuda_setup.py"))["prepare_cuda_linker"]()
(out / "cuda-link-check.json").write_text(json.dumps(cuda, indent=2))
subprocess.run([sys.executable, "-m", "venv", "--without-pip", "/tmp/e52-env"], check=True)
py = "/tmp/e52-env/bin/python"
subprocess.run([sys.executable, "-m", "pip", "--python", py, "install", "--no-cache-dir", "-q", "vllm==0.20.0",
               "transformers==5.13.0", "huggingface-hub==1.22.0", "pandas==3.0.3", "pyarrow==24.0.0"], check=True)
freeze = subprocess.run([sys.executable, "-m", "pip", "--python", py, "freeze"], capture_output=True, text=True, check=True)
(out / "environment.txt").write_text(freeze.stdout)
guard = runpy.run_path(str(root / "scripts/kaggle_process_guard.py"))["run_guarded"]
if (root / "resume").is_dir():
    shutil.copytree(root / "resume", out, dirs_exist_ok=True)
phases = {'base': ['datagen/perturb/sample.py', '--model-id', 'Qwen/Qwen3.5-4B', '--backend', 'vllm', '--pool', 'data/e62/pool.parquet', '--k', '4', '--temperature', '1.0', '--top-p', '0.95', '--top-k', '40', '--max-new-tokens', '65536', '--tensor-parallel', '1', '--text-only', '--max-num-seqs', '64', '--chunk', '4', '--allow-no-solution', '--k', '2', '--max-new-tokens', '32768', '--chunk', '16', '--out-dir', '/kaggle/working/e62-qwen-d', '--problem-keys', '01b549d01d66b9ba', '07807eaafe0600c7', '0b54136fc692e0c7', '0dbbcbfd08728f11', '11e19cd0c03e0de8', '180f13e86a8d2cfa', '1b56289ecfde2083', '1f0ccfd0d6792c8e', '20489baad1192434', '24c7c061031b8fda', '2a711b924139ac8b', '2e525d40b19b09d5', '30d9790379b75e13', '3476a1cd956a3ba6', '36e93438992d0b25', '3a8ce9180883c05b', '3c1039494fad41b9', '3dad232dd0d0485b', '415a6f5b74dd52ad', '4407179f3d1fd431', '46a9d5e8cc91218c', '4b3d1f7b07f77119', '5189a1cb37d9bb49', '5947c66bda127d5f', '5b92574398d58626', '60b8b03de8c1fcb3', '6485c31408504554', '6affe5acdbf2ba86', '6e553d58281b87a8', '73d06fcaf3d43e0c', '7854de7645da7a78', '7c78d436f1bf44de', '7f09dc8099a1e3b9', '82a630303fc655fc', '874b4a8d662051bb', '8c3c70621d2b39d8', '90fa5d0407fc184f', '96d0c8cbb3d3e4e1', '9b2f460e3191c589', '9d2b7fe09e930e55', 'a089dfafc385dec6', 'a620d45d73683080', 'aa562ae3d83a699c', 'aef9b957fbd751d8', 'b245557e58effd7a', 'b85aadf35e3aac33', 'bcf24f60d1f33342', 'c012c6845e62b0e4', 'c2e921f2a0a85366', 'caefb789123a68cb', 'd02fcbacce327cd8', 'd4ccf4347ab82805', 'd90071a72262f236', 'dbfbc95474eda75f', 'e11b8870f72aac9c', 'e67d6ee440ca3310', 'e9983f8cb318b696', 'ebcaa5cf29f5e809', 'eff33c4663d1aa29', 'f450abeca48f24e7', 'f72827b0df869f60', 'fc59e0efb203109d', '--phase', 'base', '--max-hours', '9.0']}
results = {}
for phase, argv in phases.items():
    if True:
        # One engine per T4 (E24's layout for Qwen3.5-4B), each on half of this kernel's items.
        launcher = ("import os, subprocess, sys\n"
                    f"argv = {argv!r}\n"
                    "procs = [subprocess.Popen([sys.argv[1], *argv, '--num-shards', '2', '--shard-index', str(i)],\n"
                    "         env={**os.environ, 'CUDA_VISIBLE_DEVICES': str(i)}) for i in (0, 1)]\n"
                    "sys.exit(max(p.wait() for p in procs))")
        cmd = [py, "-c", launcher, py]
    else:
        cmd = [py, *argv]
    results[phase] = guard(cmd, root, out / f"{phase}.log", timeout=34200.0
                           if phase == "variants" else 34200.0)
    (out / "execution.json").write_text(json.dumps({**results, "end_to_end_seconds": time.time() - started}, indent=2))
raise SystemExit(max(r["exit_code"] for r in results.values()))
